const t = $("Sub").item.json;
const runId = (typeof $execution !== 'undefined' && $execution.id) ? String($execution.id) : Date.now() + '-' + Math.random().toString(36).substring(2);
const isFresh = (t.triggerType || 'issue') === 'issue';
const initialState = isFresh
  ? { status: "RUNNING", runId, startedAt: new Date().toISOString(), clarificationRounds: 0, halted: false }
  : { status: "RUNNING", runId, startedAt: new Date().toISOString() };
return { json: { issueId: t.issueId, triggerType: t.triggerType || 'issue', commentBody: t.commentBody || '', runId, initialState: JSON.stringify(initialState) } };

const runData = $("Generate Run ID").item.json;
const issueData = $json;
const issue = issueData.issue || {};
const buildState = issueData.buildState || {};
const t = runData;
const prevAttempts = Number(buildState.attempts) || 0;
const attempts = prevAttempts + 1;
const prevStatus = buildState.status || '';
const isRevision = prevStatus === 'BUILD_COMPLETE';
let chatInput;
if (t.commentBody) {
  chatInput = 'A comment was posted on this Linear ticket mentioning you.

Ticket: ' + (issue.identifier || '') + ' — ' + (issue.title || '') + '
URL: ' + (issue.url || '') + '

Comment from the author:
' + t.commentBody + '

Full ticket description:
' + (issue.description || '') + '

Please review the feedback and proceed with the build.';
} else if (isRevision) {
  chatInput = 'REVISION REQUEST for ' + (issue.identifier || '') + ' — ' + (issue.title || '') + '

This ticket was previously completed and sent back for revision.

PREVIOUS SUMMARY: ' + (buildState.rollingSummary || '') + '

CURRENT TICKET DESCRIPTION:
' + (issue.description || '') + '

Please review and make the requested changes.';
} else {
  chatInput = 'Build the following from this Linear ticket:

Ticket: ' + (issue.identifier || '') + ' — ' + (issue.title || '') + '
URL: ' + (issue.url || '') + '

Description:
' + (issue.description || '') + '

Labels: ' + ((issue.labels || []).map(function(l){return l.name;}).join(', ')) + '
Priority: ' + (issue.priorityLabel || '') + '
Team: ' + ((issue.team && issue.team.name) || '') + '

Please review this ticket and build what is requested.';
}
chatInput += '

When you are done, respond with a JSON object with these fields: status (NEEDS_CLARIFICATION or BUILD_COMPLETE or BUILD_FAILED), summary, workflowIds, testResults, manualSteps, clarificationComment (only if NEEDS_CLARIFICATION).';
return { json: { chatInput, sessionId: 'linear-' + t.issueId, channel: 'C0BN97ZSKKJ', env: 'slack', issueId: t.issueId, runId: t.runId, attempts } };

const raw = $json;
const t = $('Build Chat Input').item.json;
const issueData = $('Get Issue').item.json;
const buildState = issueData.buildState || {};
const STATE_MAP = {"BACKLOG":"592edbfc-8c9b-4617-b4fe-1ff226031ea2","TODO":"3c0abcad-0ea6-4400-b034-5a8da087272b","IN_PROGRESS":"fac1e4ba-bd0c-464d-b7d8-6e9610dded2b","IN_REVIEW":"3247f65d-3c64-416b-80a4-465d611309a9","DONE":"1b77b415-6f1e-40b9-b342-e59acd7fefca","CANCELED":"cdb3b68f-252b-4d4a-9c83-421e73384186"};
let text;
if (typeof raw === 'string') { text = raw; }
else if (raw.output) { text = raw.output; }
else if (raw.response) { text = raw.response; }
else if (raw.error || raw.message) { text = 'ERROR: ' + (raw.error && raw.error.message || raw.message || JSON.stringify(raw)); }
else { text = JSON.stringify(raw); }
const hadError = !!(raw && (raw.error || (typeof raw.output === 'undefined' && typeof raw.message === 'string')));
let parsed = null;
const brace = text.match(/\{[\s\S]*\}/);
if (brace) { try { parsed = JSON.parse(brace[0]); } catch(e) { parsed = null; } }
let status, summary, workflowIds, testResults, manualSteps, clarificationComment;
if (parsed && parsed.status) {
  status = String(parsed.status).toUpperCase();
  summary = parsed.summary || '';
  workflowIds = Array.isArray(parsed.workflowIds) ? parsed.workflowIds : [];
  testResults = parsed.testResults || '';
  manualSteps = Array.isArray(parsed.manualSteps) ? parsed.manualSteps : [];
  clarificationComment = parsed.clarificationComment || '';
} else {
  status = 'UNKNOWN';
  summary = text.substring(0, 1000);
  workflowIds = [];
  testResults = '';
  manualSteps = [];
  clarificationComment = '';
}
if (hadError) { status = 'BUILD_FAILED'; if (!summary) { summary = text.substring(0, 1000); } }
if (!['NEEDS_CLARIFICATION','BUILD_COMPLETE','BUILD_FAILED'].includes(status)) { status = 'UNKNOWN'; }
let clarificationRounds = Number(buildState.clarificationRounds) || 0;
if (status === 'NEEDS_CLARIFICATION') { clarificationRounds += 1; }
const shouldHalt = (status === 'NEEDS_CLARIFICATION' && clarificationRounds >= 3);
let linearStateId, commentBody, slackMessage;
const issueIdentifier = (issueData.issue && issueData.issue.identifier) || '';
const issueTitle = (issueData.issue && issueData.issue.title) || '';
const issueUrl = (issueData.issue && issueData.issue.url) || '';
if (shouldHalt) {
  status = 'HALTED';
  linearStateId = STATE_MAP.IN_PROGRESS;
  commentBody = '⏸ **Halted after ' + clarificationRounds + ' clarification rounds**\n\n' + (clarificationComment || summary || 'The ticket needs human review.') + '\n\nNo further builds will start until you post a comment mentioning me with reset.';
  slackMessage = '⏸ Halted after ' + clarificationRounds + ' clarification rounds on ' + issueIdentifier + ': ' + issueTitle + '\n' + (clarificationComment || summary || '') + '\nLinear: ' + issueUrl;
} else if (status === 'NEEDS_CLARIFICATION') {
  linearStateId = STATE_MAP.IN_PROGRESS;
  commentBody = '🔍 **Needs Clarification**\n\n' + clarificationComment + '\n\nPlease update the ticket and mention me when ready.';
  slackMessage = '❓ Clarification needed on ' + issueIdentifier + ': ' + issueTitle + '\n' + clarificationComment + '\nLinear: ' + issueUrl;
} else if (status === 'BUILD_COMPLETE') {
  linearStateId = STATE_MAP.IN_REVIEW;
  commentBody = '✅ **Build Complete**\n\n' + summary + '\n\n**Workflows affected:** ' + (workflowIds.length > 0 ? workflowIds.join(', ') : 'None') + '\n**Test results:** ' + (testResults || 'N/A') + '\n**Manual steps:**\n' + (manualSteps.length > 0 ? manualSteps.map(function(s){return '- ' + s;}).join('\n') : 'None') + '\n\nReady for review!';
  slackMessage = '✅ Build complete for ' + issueIdentifier + ': ' + issueTitle + '\n' + summary + '\nLinear: ' + issueUrl;
} else if (status === 'BUILD_FAILED') {
  linearStateId = STATE_MAP.CANCELED;
  commentBody = '❌ **Build Failed**\n\n' + summary + '\n\n**Test results:** ' + (testResults || 'N/A') + '\n\nMention me in a comment to retry.';
  slackMessage = '❌ Error on ' + issueIdentifier + ': ' + issueTitle + '\n' + summary + '\nLinear: ' + issueUrl;
} else {
  linearStateId = STATE_MAP.IN_PROGRESS;
  commentBody = '⚠ **Unexpected Result**\n\n' + (summary || 'No structured result was returned.') + '\n\nPlease check manually.';
  slackMessage = '⚠ Unexpected result on ' + issueIdentifier + ': ' + issueTitle + '\n' + (summary || '') + '\nLinear: ' + issueUrl;
}
return { json: { status, summary, workflowIds, testResults, manualSteps, clarificationComment, clarificationRounds, shouldHalt, linearStateId, commentBody, slackMessage, issueId: t.issueId, runId: t.runId, issueIdentifier, issueTitle, issueUrl, finishedAt: new Date().toISOString() } };

const drainResult = $json;
const pendingFeedback = drainResult.pendingFeedback || [];
const issueId = drainResult.issueId || $('Generate Run ID').item.json.issueId;
if (pendingFeedback.length === 0) {
  return { json: { shouldRedispatch: false, issueId } };
}
return { json: { shouldRedispatch: true, issueId, triggerType: 'comment', commentBody: pendingFeedback.join('\n\n') } };
